CREATE TABLE `vivienda` (
  `idVivienda` double NOT NULL,
  `accesoVivienda` varchar(50) DEFAULT NULL,
  `tipoVivienda` varchar(35) NOT NULL,
  `pisoMaterial` varchar(75) NOT NULL,
  `pisoEstado` varchar(7) NOT NULL,
  `paredMaterial` varchar(50) DEFAULT NULL,
  `paredEstado` varchar(7) DEFAULT NULL,
  `cubiertaTecho` varchar(72) DEFAULT NULL,
  `cubiertaEstado` varchar(7) DEFAULT NULL,
  `eliminaBasura` varchar(45) DEFAULT NULL,
  `Ubicacion_idUbicacion` bigint NOT NULL,
  `ServicioHigienico_idServicioHigienico` int NOT NULL,
  PRIMARY KEY (`idVivienda`,`ServicioHigienico_idServicioHigienico`),
  KEY `fk_Vivienda_Ubicacion_idx` (`Ubicacion_idUbicacion`),
  KEY `fk_Vivienda_ServicioHigienico1_idx` (`ServicioHigienico_idServicioHigienico`),
