  CONSTRAINT `fk_Vivienda_Ubicacion` FOREIGN KEY (`Ubicacion_idUbicacion`) REFERENCES `ubicacion` (`idUbicacion`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
